using System;using System.IO;using System.Linq;using System.Threading.Tasks;using System.Collections.Generic;using UnityEngine;using UnityEngine.InputSystem;using UnityEngine.InputSystem.LowLevel;using ProjectWait.M.Elevator;using Object=UnityEngine.Object;
public static class VerifyCopingGuided
{
 const string D="Assets/M/CodexTemp/ElevatorCoping_20261030~/";static ElevatorLesson l;static ElevatorDesktopControls c;static ElevatorScenarioDirector s;static List<object> checks=new List<object>();static int passed;
 static Vector2 Centre=>new Vector2(Screen.width*.5f,Screen.height*.5f);
 static void Check(bool ok,string name){checks.Add(new{name,passed=ok});if(!ok)throw new Exception(name);passed++;}
 static void Clear(){l.presentation.space.overlay.Advance(2);}
 static async Task Wait(Func<bool> test,string description,int milliseconds=10000){int n=0;while(!test()&&n<milliseconds){await Task.Delay(50);n+=50;}Check(test(),description);}
 static async Task Mouse(Vector2 p,bool down=false){var state=new MouseState{position=p};if(down)state=state.WithButton(MouseButton.Left,true);InputSystem.QueueStateEvent(UnityEngine.InputSystem.Mouse.current,state);await Task.Delay(90);}
 static async Task Aim(ElevatorObservation o){var collider=o.GetComponent<Collider>();var p=collider?collider.bounds.center:o.transform.position;var r=Quaternion.LookRotation(p-l.playerCamera.transform.position).eulerAngles;c.SetLookAngles(r.y,Mathf.DeltaAngle(0,r.x));await Mouse(Centre);await Task.Delay(100);}
 static async Task Click(ElevatorObservation o){await Wait(()=>l.CanInteract(o.clue),"Object is actionable: "+o.name);await Aim(o);Check(c.HoverTargetName==o.name,"Ray selects guided object: "+o.name);await Mouse(Centre,true);await Mouse(Centre);Check(l.view.ChoiceButtons.Count==0,"Progress uses objects without dialogue-choice buttons");}
 static async Task Primary(){await Task.Delay(100);Check(s.PrimaryTarget,"A guided physical target is assigned");Check(s.PrimaryTarget.shapeHighlight&&s.PrimaryTarget.shapeHighlight.Visible,"Guided target glows before hovering");await Click(s.PrimaryTarget);}
 static async Task Shot(string name){await Task.Delay(130);ScreenCapture.CaptureScreenshot(D+name+".png");await Task.Delay(150);}
 public static async Task<string> Main()
 {
  for(int i=0;i<100;i++){l=Object.FindFirstObjectByType<ElevatorLesson>();if(Application.isPlaying&&l&&l.Flow!=null)break;await Task.Delay(100);}c=Object.FindFirstObjectByType<ElevatorDesktopControls>();s=l.scenario;checks.Clear();passed=0;string error=null;int frame=Time.frameCount;bool response=l.simulateNoResponse;
  var old=InputSystem.settings;var temp=Object.Instantiate(old);temp.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;temp.editorInputBehaviorInPlayMode=InputSettings.EditorInputBehaviorInPlayMode.AllDeviceInputAlwaysGoesToGameView;InputSystem.settings=temp;var hardware=UnityEngine.InputSystem.Mouse.current;bool enabled=hardware!=null&&hardware.enabled;if(enabled)InputSystem.DisableDevice(hardware);var mouse=InputSystem.AddDevice<UnityEngine.InputSystem.Mouse>("GuidedCopingQAMouse");mouse.MakeCurrent();
  try
  {
   Check(s.objectGuidedScene,"Separate object-interaction test scene enabled");l.simulateNoResponse=false;l.Restart();Clear();await Task.Delay(160);Check(l.view.ChoiceButtons.Count==0,"Test starts without dialogue choices");Check(s.PrimaryTarget&&s.PrimaryTarget.clue==ElevatorClue.LobbyCall,"Friend directs player to the lower call button");await Shot("10_Test_ObjectGuidance");await Primary();Check(l.Flow.Step==ElevatorStep.Entering,"Physical call begins boarding");
   await Task.Delay(1500);c.SetLookAngles(280,50);await Task.Delay(550);var expected=(l.friend.position+Vector3.up*1.05f-l.playerCamera.transform.position).normalized;Check(Vector3.Dot(l.playerCamera.transform.forward,expected)>.94f,"Boarding timeline corrects a deliberately wrong view");await Shot("11_Test_BoardingGaze");await Wait(()=>l.Flow.Step==ElevatorStep.Boarding&&!l.CinematicBlocking,"Boarding ends and releases interaction",7000);
   await Primary();Check(l.Flow.DestinationSelected,"Direct floor button chooses 1F");await Primary();Check(l.Flow.Step==ElevatorStep.Proposal,"Direct friend interaction accepts the ball");var notice=l.CollectObservations().First(o=>o.gameObject.activeInHierarchy&&o.clue==ElevatorClue.Notice);Check(s.IsGuidedTarget(notice)&&notice.shapeHighlight.Visible,"Poster provides the alternative no-jump object action");await Primary();Check(l.Flow.Step==ElevatorStep.Jump,"Direct friend interaction requests shot demonstration");c.SetLookAngles(0,60);await Task.Delay(600);expected=(l.friend.position+Vector3.up*1.05f-l.playerCamera.transform.position).normalized;Check(Vector3.Dot(l.playerCamera.transform.forward,expected)>.94f,"Shot timeline keeps attention on the friend");await Shot("12_Test_ShotGaze");
   await Wait(()=>l.Flow.Step==ElevatorStep.Stopped&&l.Flow.CanObserve&&!l.CinematicBlocking,"Fault intro releases direct investigation",6500);Check(l.Flow.JumpCount==1,"Guided shot branch contains one friend jump");await Shot("13_Test_FaultGuidance");await Primary();await Wait(()=>l.Flow.Step==ElevatorStep.Call&&!l.CinematicBlocking,"Intercom connects and releases speech interaction",5000);await Primary();Check(l.Flow.SituationReported&&!l.Flow.IdentityFound,"Direct communication reports the situation first");await Primary();Check(l.Flow.IdentityFound,"Direct identity-plate inspection identifies the lift");await Primary();Check(l.Flow.LocationReported,"Direct communication reports the checked location");await Primary();Check(l.Flow.Step==ElevatorStep.Waiting,"Direct acknowledgement follows operator advice");await Primary();Check(l.Flow.Step==ElevatorStep.WaitingFade,"Direct friend interaction begins safe waiting fade");
   l.pauseMenu.Pause();float elapsed=l.Flow.Elapsed;await Task.Delay(220);Check(l.Flow.Elapsed==elapsed&&Time.timeScale==0,"Pause freezes the waiting timeline");var position=RectTransformUtility.WorldToScreenPoint(l.playerCamera,l.pauseMenu.resumeButton.transform.position);await Mouse(position);Check(c.HoverTargetName==l.pauseMenu.resumeButton.name,"PC free pointer reaches world-space resume button");await Mouse(position,true);await Mouse(position);Check(!l.pauseMenu.IsPaused&&Time.timeScale==1,"World-space pause button resumes the scenario");
   await Wait(()=>l.Flow.Step==ElevatorStep.Rescue&&l.Flow.ReadyToExit&&!l.CinematicBlocking,"Faded wait leads to checked rescue",10000);Check(s.PrimaryTarget&&s.PrimaryTarget.clue==ElevatorClue.Rescuer,"Staff is the highlighted rescue object");await Shot("14_Test_StaffRescue");await Primary();await Wait(()=>l.Flow.Step==ElevatorStep.ReturnLobby&&!l.CinematicBlocking,"Player follows staff out of the lift",6500);await Primary();await Wait(()=>l.Flow.Step==ElevatorStep.GroundFloor&&!l.CinematicBlocking,"Staff-guided stair transition reaches 1F",5500);await Primary();await Wait(()=>l.Flow.Step==ElevatorStep.Complete&&!l.CinematicBlocking,"Direct exit interaction completes the journey",8500);Check(l.view.ChoiceButtons.Count==0&&l.view.spatial.notebook.gameObject.activeInHierarchy,"Completion uses the world notebook without dialogue choices");await Shot("15_Test_Complete");
   l.DeveloperJump(2);Clear();await Task.Delay(100);await Click(notice);Check(l.Flow.Step==ElevatorStep.Travel&&l.Flow.JumpCount==0,"Poster action takes the no-jump branch");l.Advance(4);l.Advance(2);Clear();Check(l.Flow.Step==ElevatorStep.Stopped&&l.Flow.JumpCount==0,"No-jump guided branch still reaches the fault");
   l.simulateNoResponse=true;l.DeveloperJump(3);l.Advance(2);Clear();await Task.Delay(100);await Primary();l.Advance(3);Clear();await Task.Delay(100);Check(l.Flow.Step==ElevatorStep.Unanswered&&s.PrimaryTarget.clue==ElevatorClue.Phone,"No response highlights the phone fallback");await Primary();Check(l.Flow.Step==ElevatorStep.Call&&l.Flow.UsedPhone,"Phone object starts the simulated 119 alternative");l.simulateNoResponse=false;l.Restart();Clear();int f=Time.frameCount;await Task.Delay(200);Check(Time.frameCount>f&&f>frame,"Live player frames advanced through the full direct-interaction story");
  }
  catch(Exception e){error=e.ToString();ScreenCapture.CaptureScreenshot(D+"GuidedFailure.png");}
  finally{if(l.pauseMenu.IsPaused)l.pauseMenu.Resume();l.simulateNoResponse=response;InputSystem.RemoveDevice(mouse);if(enabled)InputSystem.EnableDevice(hardware);hardware?.MakeCurrent();InputSystem.settings=old;Object.Destroy(temp);}
  var report=Newtonsoft.Json.JsonConvert.SerializeObject(new{success=error==null,passed,checks,error,frameStart=frame,frameEnd=Time.frameCount,state=l.Snapshot()},Newtonsoft.Json.Formatting.Indented);File.WriteAllText(D+"GuidedVerification.json",report);return report;
 }
}
